//! 🪆️ Sort original member key ordinals under controlled work without copying authored identities.
use crate::snapshot::LayoutSnapshot;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteSnapshotPhase,transfer};
use semio_framework_value::{ValueError,ValueRefusalKind};
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn compare(a:Option<&str>,b:Option<&str>,control:&mut SqliteSnapshotControl<'_>)->Result<std::cmp::Ordering,ValueError>{let(Some(a),Some(b))=(a,b)else{return Ok(a.is_some().cmp(&b.is_some()))};for offset in(0..a.len().min(b.len())).step_by(256){control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,offset,a.len().min(b.len()))?;let end=(offset+256).min(a.len().min(b.len()));let order=a.as_bytes()[offset..end].cmp(&b.as_bytes()[offset..end]);if !order.is_eq(){return Ok(order)}}Ok(a.len().cmp(&b.len()))}
pub fn validate(snapshot:&LayoutSnapshot,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let count=snapshot.pages.len().checked_add(1).ok_or_else(||invalid("Layout member address extent overflow"))?;let mut positions=transfer::reserve(count,control)?;let key=|at:usize,column:usize|{let member=if at==0{snapshot.background_drawing.as_ref()}else{snapshot.pages[at-1].background_drawing.as_ref()};member.map(|member|if column==0{member.handle.child_id.as_str()}else{member.handle.target.artifact_id.as_str()})};for column in 0..2{positions.clear();for at in 0..count{if key(at,column)==Some(""){return Err(invalid("Layout Drawing member identity is empty"))}positions.push(at);if at%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,at,count)?;}}transfer::heap_sort(&mut positions,SqliteSnapshotPhase::ReconstructSnapshot,control,|a,b,control|compare(key(*a,column),key(*b,column),control))?;for pair in positions.windows(2){let a=key(pair[0],column);let b=key(pair[1],column);if a.is_some()&&b.is_some()&&compare(a,b,control)?.is_eq(){return Err(invalid("Layout Drawing member aliases another child identity or target"))}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,0)?;}}Ok(())}
